// ============================================================
// CREDO HR-Portal — Offboarding angelegt
// Benachrichtigung an HR: Neuer Offboarding-Vorgang
// ============================================================

const CONFIG = {
  hrEmail: 'personal@credo-gruppe.de',
  portalUrl: 'https://hr.fes-credo.de'
};

try {
  const item = $input.first().json;
  const data = item.body || item;
  const { displayId, employeeName, employeeFirstName, employeeLastName, organization, exitType, lastWorkingDay } = data;

  const name = employeeName || [employeeFirstName, employeeLastName].filter(Boolean).join(' ') || 'Unbekannt';
  const orgName = organization || 'CREDO';
  const lwdFormatted = lastWorkingDay ? new Date(lastWorkingDay).toLocaleDateString('de-DE', { day: '2-digit', month: '2-digit', year: 'numeric' }) : 'k.A.';

  const exitTypeLabels = {
    'KUENDIGUNG_ARBEITNEHMER': 'K\u00fcndigung (Arbeitnehmer)',
    'KUENDIGUNG_ARBEITGEBER': 'K\u00fcndigung (Arbeitgeber)',
    'AUFHEBUNGSVERTRAG': 'Aufhebungsvertrag',
    'BEFRISTUNGSENDE': 'Befristungsende',
    'RENTE_PENSION': 'Rente/Pension',
    'ERWERBSMINDERUNG': 'Erwerbsminderung',
    'ENTLASSUNG_BEAMTER': 'Entlassung (Beamter)',
    'VERSETZUNG': 'Versetzung',
    'TOD': 'Tod',
    'SONSTIGES': 'Sonstiges'
  };
  const exitLabel = exitTypeLabels[exitType] || exitType || 'k.A.';

  const htmlBody = `<!DOCTYPE html>
<html lang="de">
<head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"></head>
<body style="margin:0;padding:0;background-color:#f5f5f5;font-family:Calibri,Arial,sans-serif;">
<table width="100%" cellpadding="0" cellspacing="0" style="background-color:#f5f5f5;padding:20px 0;">
<tr><td align="center">
<table width="600" cellpadding="0" cellspacing="0" style="background-color:#ffffff;border-radius:8px;overflow:hidden;">
  <tr><td style="background-color:#005d6a;padding:25px 40px;">
    <h1 style="color:#ffffff;font-family:'ITC Avant Garde Gothic',Arial Black,Arial,sans-serif;font-size:22px;margin:0;">Offboarding-Benachrichtigung</h1>
  </td></tr>
  <tr><td style="padding:35px 40px;">
    <div style="background-color:#fff3e0;border-left:4px solid #FBC900;padding:15px 20px;border-radius:4px;margin:0 0 25px;">
      <p style="color:#e65100;font-size:15px;font-weight:bold;margin:0;">Neuer Offboarding-Vorgang angelegt</p>
    </div>
    <table cellpadding="8" cellspacing="0" style="width:100%;border-collapse:collapse;margin:0 0 25px;">
      <tr style="border-bottom:1px solid #eeeeee;"><td style="color:#666;font-size:14px;width:160px;">Vorgang</td><td style="color:#333;font-size:14px;font-weight:bold;">${displayId || 'k.A.'}</td></tr>
      <tr style="border-bottom:1px solid #eeeeee;"><td style="color:#666;font-size:14px;">Mitarbeiter/in</td><td style="color:#333;font-size:14px;font-weight:bold;">${name}</td></tr>
      <tr style="border-bottom:1px solid #eeeeee;"><td style="color:#666;font-size:14px;">Einrichtung</td><td style="color:#333;font-size:14px;">${orgName}</td></tr>
      <tr style="border-bottom:1px solid #eeeeee;"><td style="color:#666;font-size:14px;">Austrittsgrund</td><td style="color:#333;font-size:14px;">${exitLabel}</td></tr>
      <tr><td style="color:#666;font-size:14px;">Letzter Arbeitstag</td><td style="color:#333;font-size:14px;font-weight:bold;">${lwdFormatted}</td></tr>
    </table>
    <table cellpadding="0" cellspacing="0" style="margin:0 auto 20px;"><tr><td align="center" style="background-color:#005d6a;border-radius:6px;">
      <a href="${CONFIG.portalUrl}/offboarding" target="_blank" style="display:inline-block;padding:12px 35px;color:#ffffff;font-size:15px;font-weight:bold;text-decoration:none;">Im HR-Portal oeffnen</a>
    </td></tr></table>
  </td></tr>
  <tr><td style="padding:0;"><table width="100%" cellpadding="0" cellspacing="0"><tr>
    <td width="50%" style="height:4px;background-color:#DADADA;"></td>
    <td width="12.5%" style="height:4px;background-color:#FBC900;"></td>
    <td width="12.5%" style="height:4px;background-color:#6BAA24;"></td>
    <td width="12.5%" style="height:4px;background-color:#E2001A;"></td>
    <td width="12.5%" style="height:4px;background-color:#009AC6;"></td>
  </tr></table></td></tr>
  <tr><td style="background-color:#f9f9f9;padding:15px 40px;text-align:center;">
    <p style="color:#999;font-size:11px;margin:0;">Automatische Benachrichtigung des CREDO HR-Portals</p>
  </td></tr>
</table>
</td></tr>
</table>
</body></html>`;

  return [{ json: { to: CONFIG.hrEmail, subject: `[HR-Portal] Neuer Offboarding-Vorgang angelegt: ${name} (${orgName})`, html: htmlBody } }];
} catch (error) {
  console.error('[offboarding-created] Fehler:', error.message);
  return [{ json: { error: error.message, event: 'offboarding-created' } }];
}

// ============================================================
// CREDO HR-Portal — Abteilung zugewiesen
// E-Mail an Abteilung mit Magic-Link
// ============================================================

try {
  const item = $input.first().json;
  const data = item.body || item;
  const { displayId, employeeName, employeeFirstName, employeeLastName, organization, departmentName, departmentKey, email, magicLink, lastWorkingDay, taskCount } = data;

  const name = employeeName || [employeeFirstName, employeeLastName].filter(Boolean).join(' ') || 'Unbekannt';
  const orgName = organization || 'CREDO';
  const lwdFormatted = lastWorkingDay ? new Date(lastWorkingDay).toLocaleDateString('de-DE', { day: '2-digit', month: '2-digit', year: 'numeric' }) : 'k.A.';
  const deptName = departmentName || departmentKey || 'Abteilung';

  const htmlBody = `<!DOCTYPE html>
<html lang="de">
<head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"></head>
<body style="margin:0;padding:0;background-color:#f5f5f5;font-family:Calibri,Arial,sans-serif;">
<table width="100%" cellpadding="0" cellspacing="0" style="background-color:#f5f5f5;padding:20px 0;">
<tr><td align="center">
<table width="600" cellpadding="0" cellspacing="0" style="background-color:#ffffff;border-radius:8px;overflow:hidden;">
  <tr><td style="background-color:#005d6a;padding:30px 40px;text-align:center;">
    <h1 style="color:#ffffff;font-family:'ITC Avant Garde Gothic',Arial Black,Arial,sans-serif;font-size:28px;margin:0;letter-spacing:2px;">CREDO</h1>
    <p style="color:#ffffff;font-size:12px;margin:5px 0 0;letter-spacing:3px;">Glauben &bull; Leben &bull; Gemeinsam</p>
  </td></tr>
  <tr><td style="padding:40px;">
    <h2 style="color:#005d6a;font-size:20px;margin:0 0 20px;">Offboarding-Aufgaben f\u00fcr ${deptName}</h2>
    <p style="color:#333;font-size:15px;line-height:1.6;margin:0 0 15px;">Sehr geehrtes Team ${deptName},</p>
    <p style="color:#333;font-size:15px;line-height:1.6;margin:0 0 15px;">im Rahmen des Offboarding-Vorgangs f\u00fcr <strong>${name}</strong> (${orgName}) wurden Ihnen Aufgaben zugewiesen. Bitte bearbeiten Sie diese zeitnah.</p>
    <table cellpadding="8" cellspacing="0" style="width:100%;border-collapse:collapse;margin:0 0 25px;">
      <tr style="border-bottom:1px solid #eee;"><td style="color:#666;font-size:14px;width:160px;">Vorgang</td><td style="color:#333;font-size:14px;font-weight:bold;">${displayId || 'k.A.'}</td></tr>
      <tr style="border-bottom:1px solid #eee;"><td style="color:#666;font-size:14px;">Mitarbeiter/in</td><td style="color:#333;font-size:14px;font-weight:bold;">${name}</td></tr>
      <tr style="border-bottom:1px solid #eee;"><td style="color:#666;font-size:14px;">Letzter Arbeitstag</td><td style="color:#333;font-size:14px;">${lwdFormatted}</td></tr>
      <tr><td style="color:#666;font-size:14px;">Offene Aufgaben</td><td style="color:#333;font-size:14px;font-weight:bold;">${taskCount || 'k.A.'}</td></tr>
    </table>
    <table cellpadding="0" cellspacing="0" style="margin:0 auto 25px;"><tr><td align="center" style="background-color:#005d6a;border-radius:6px;">
      <a href="${magicLink}" target="_blank" style="display:inline-block;padding:14px 40px;color:#ffffff;font-size:16px;font-weight:bold;text-decoration:none;">Aufgaben oeffnen</a>
    </td></tr></table>
    <p style="color:#666;font-size:13px;line-height:1.5;margin:0 0 10px;">Falls der Button nicht funktioniert, kopieren Sie diesen Link in Ihren Browser:</p>
    <p style="color:#005d6a;font-size:13px;line-height:1.5;word-break:break-all;margin:0 0 25px;">${magicLink}</p>
    <hr style="border:none;border-top:1px solid #eee;margin:25px 0;">
    <p style="color:#666;font-size:13px;line-height:1.5;margin:0;">Bei Fragen wenden Sie sich an <a href="mailto:personal@credo-gruppe.de" style="color:#005d6a;">personal@credo-gruppe.de</a>.</p>
  </td></tr>
  <tr><td style="padding:0;"><table width="100%" cellpadding="0" cellspacing="0"><tr>
    <td width="50%" style="height:4px;background-color:#DADADA;"></td>
    <td width="12.5%" style="height:4px;background-color:#FBC900;"></td>
    <td width="12.5%" style="height:4px;background-color:#6BAA24;"></td>
    <td width="12.5%" style="height:4px;background-color:#E2001A;"></td>
    <td width="12.5%" style="height:4px;background-color:#009AC6;"></td>
  </tr></table></td></tr>
  <tr><td style="background-color:#f9f9f9;padding:20px 40px;text-align:center;">
    <p style="color:#999;font-size:11px;line-height:1.5;margin:0;">Christlicher Schulverein Minden e.V. &middot; Kingsleyallee 6 &middot; 32425 Minden<br>Tel. 0571 388 60-148 &middot; <a href="https://fes-minden.de" style="color:#005d6a;text-decoration:none;">fes-minden.de</a></p>
  </td></tr>
</table>
</td></tr>
</table>
</body></html>`;

  return [{ json: { to: email, subject: `Offboarding-Aufgaben f\u00fcr ${deptName}: ${name} (${orgName})`, html: htmlBody } }];
} catch (error) {
  console.error('[offboarding-department-assigned] Fehler:', error.message);
  return [{ json: { error: error.message, event: 'offboarding-department-assigned' } }];
}

// ============================================================
// CREDO HR-Portal — Aufgabe erledigt
// Benachrichtigung an HR ueber Fortschritt
// ============================================================

const CONFIG = {
  hrEmail: 'personal@credo-gruppe.de'
};

try {
  const item = $input.first().json;
  const data = item.body || item;
  const { displayId, employeeName, employeeFirstName, employeeLastName, organization, departmentName, departmentKey, taskTitle, completedCount, totalCount } = data;

  const name = employeeName || [employeeFirstName, employeeLastName].filter(Boolean).join(' ') || 'Unbekannt';
  const orgName = organization || 'CREDO';
  const deptName = departmentName || departmentKey || 'Abteilung';
  const progress = totalCount > 0 ? Math.round((completedCount / totalCount) * 100) : 0;

  // Fortschrittsbalken-Farbe
  const progressColor = progress >= 100 ? '#6BAA24' : progress >= 50 ? '#009AC6' : '#FBC900';

  const htmlBody = `<!DOCTYPE html>
<html lang="de">
<head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"></head>
<body style="margin:0;padding:0;background-color:#f5f5f5;font-family:Calibri,Arial,sans-serif;">
<table width="100%" cellpadding="0" cellspacing="0" style="background-color:#f5f5f5;padding:20px 0;">
<tr><td align="center">
<table width="600" cellpadding="0" cellspacing="0" style="background-color:#ffffff;border-radius:8px;overflow:hidden;">
  <tr><td style="background-color:#005d6a;padding:25px 40px;">
    <h1 style="color:#ffffff;font-family:'ITC Avant Garde Gothic',Arial Black,Arial,sans-serif;font-size:22px;margin:0;">Offboarding-Fortschritt</h1>
  </td></tr>
  <tr><td style="padding:35px 40px;">
    <div style="background-color:#e8f5e9;border-left:4px solid #6BAA24;padding:15px 20px;border-radius:4px;margin:0 0 25px;">
      <p style="color:#2e7d32;font-size:15px;font-weight:bold;margin:0;">${deptName} hat Aufgabe erledigt</p>
    </div>
    <table cellpadding="8" cellspacing="0" style="width:100%;border-collapse:collapse;margin:0 0 20px;">
      <tr style="border-bottom:1px solid #eee;"><td style="color:#666;font-size:14px;width:160px;">Vorgang</td><td style="color:#333;font-size:14px;font-weight:bold;">${displayId || 'k.A.'}</td></tr>
      <tr style="border-bottom:1px solid #eee;"><td style="color:#666;font-size:14px;">Mitarbeiter/in</td><td style="color:#333;font-size:14px;">${name}</td></tr>
      <tr style="border-bottom:1px solid #eee;"><td style="color:#666;font-size:14px;">Abteilung</td><td style="color:#333;font-size:14px;font-weight:bold;">${deptName}</td></tr>
      <tr><td style="color:#666;font-size:14px;">Erledigte Aufgabe</td><td style="color:#333;font-size:14px;">${taskTitle || 'k.A.'}</td></tr>
    </table>
    <p style="color:#333;font-size:14px;margin:0 0 8px;"><strong>Fortschritt: ${progress}%</strong> (${completedCount || 0} von ${totalCount || 0})</p>
    <table width="100%" cellpadding="0" cellspacing="0" style="margin:0 0 25px;"><tr>
      <td style="background-color:#eeeeee;border-radius:4px;height:12px;padding:0;">
        <div style="background-color:${progressColor};width:${progress}%;height:12px;border-radius:4px;min-width:${progress > 0 ? '12px' : '0'};"></div>
      </td>
    </tr></table>
  </td></tr>
  <tr><td style="padding:0;"><table width="100%" cellpadding="0" cellspacing="0"><tr>
    <td width="50%" style="height:4px;background-color:#DADADA;"></td>
    <td width="12.5%" style="height:4px;background-color:#FBC900;"></td>
    <td width="12.5%" style="height:4px;background-color:#6BAA24;"></td>
    <td width="12.5%" style="height:4px;background-color:#E2001A;"></td>
    <td width="12.5%" style="height:4px;background-color:#009AC6;"></td>
  </tr></table></td></tr>
  <tr><td style="background-color:#f9f9f9;padding:15px 40px;text-align:center;">
    <p style="color:#999;font-size:11px;margin:0;">Automatische Benachrichtigung des CREDO HR-Portals</p>
  </td></tr>
</table>
</td></tr>
</table>
</body></html>`;

  return [{ json: { to: CONFIG.hrEmail, subject: `[HR-Portal] ${deptName} hat Aufgabe erledigt: ${taskTitle || 'Aufgabe'} (Fortschritt: ${progress}%)`, html: htmlBody } }];
} catch (error) {
  console.error('[offboarding-task-completed] Fehler:', error.message);
  return [{ json: { error: error.message, event: 'offboarding-task-completed' } }];
}

// ============================================================
// CREDO HR-Portal — Abteilung komplett
// Benachrichtigung an HR: Alle Aufgaben einer Abteilung erledigt
// ============================================================

const CONFIG = {
  hrEmail: 'personal@credo-gruppe.de'
};

try {
  const item = $input.first().json;
  const data = item.body || item;
  const { displayId, employeeName, employeeFirstName, employeeLastName, organization, departmentName, departmentKey, remainingDepartments } = data;

  const name = employeeName || [employeeFirstName, employeeLastName].filter(Boolean).join(' ') || 'Unbekannt';
  const orgName = organization || 'CREDO';
  const deptName = departmentName || departmentKey || 'Abteilung';
  const remaining = remainingDepartments !== undefined ? remainingDepartments : 'k.A.';

  const htmlBody = `<!DOCTYPE html>
<html lang="de">
<head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"></head>
<body style="margin:0;padding:0;background-color:#f5f5f5;font-family:Calibri,Arial,sans-serif;">
<table width="100%" cellpadding="0" cellspacing="0" style="background-color:#f5f5f5;padding:20px 0;">
<tr><td align="center">
<table width="600" cellpadding="0" cellspacing="0" style="background-color:#ffffff;border-radius:8px;overflow:hidden;">
  <tr><td style="background-color:#005d6a;padding:25px 40px;">
    <h1 style="color:#ffffff;font-family:'ITC Avant Garde Gothic',Arial Black,Arial,sans-serif;font-size:22px;margin:0;">Offboarding-Fortschritt</h1>
  </td></tr>
  <tr><td style="padding:35px 40px;">
    <div style="background-color:#e3f2fd;border-left:4px solid #009AC6;padding:15px 20px;border-radius:4px;margin:0 0 25px;">
      <p style="color:#0277bd;font-size:15px;font-weight:bold;margin:0;">${deptName} hat alle Offboarding-Aufgaben erledigt</p>
    </div>
    <table cellpadding="8" cellspacing="0" style="width:100%;border-collapse:collapse;margin:0 0 25px;">
      <tr style="border-bottom:1px solid #eee;"><td style="color:#666;font-size:14px;width:160px;">Vorgang</td><td style="color:#333;font-size:14px;font-weight:bold;">${displayId || 'k.A.'}</td></tr>
      <tr style="border-bottom:1px solid #eee;"><td style="color:#666;font-size:14px;">Mitarbeiter/in</td><td style="color:#333;font-size:14px;font-weight:bold;">${name}</td></tr>
      <tr style="border-bottom:1px solid #eee;"><td style="color:#666;font-size:14px;">Einrichtung</td><td style="color:#333;font-size:14px;">${orgName}</td></tr>
      <tr style="border-bottom:1px solid #eee;"><td style="color:#666;font-size:14px;">Abteilung</td><td style="color:#333;font-size:14px;font-weight:bold;">${deptName}</td></tr>
      <tr><td style="color:#666;font-size:14px;">Verbleibende Abt.</td><td style="color:#333;font-size:14px;">${remaining}</td></tr>
    </table>
    <p style="color:#333;font-size:15px;line-height:1.6;margin:0;">${remaining === 0 ? 'Alle Abteilungen haben ihre Aufgaben erledigt. Der Offboarding-Vorgang kann abgeschlossen werden.' : 'Es warten noch ' + remaining + ' Abteilung(en) auf Erledigung.'}</p>
  </td></tr>
  <tr><td style="padding:0;"><table width="100%" cellpadding="0" cellspacing="0"><tr>
    <td width="50%" style="height:4px;background-color:#DADADA;"></td>
    <td width="12.5%" style="height:4px;background-color:#FBC900;"></td>
    <td width="12.5%" style="height:4px;background-color:#6BAA24;"></td>
    <td width="12.5%" style="height:4px;background-color:#E2001A;"></td>
    <td width="12.5%" style="height:4px;background-color:#009AC6;"></td>
  </tr></table></td></tr>
  <tr><td style="background-color:#f9f9f9;padding:15px 40px;text-align:center;">
    <p style="color:#999;font-size:11px;margin:0;">Automatische Benachrichtigung des CREDO HR-Portals</p>
  </td></tr>
</table>
</td></tr>
</table>
</body></html>`;

  return [{ json: { to: CONFIG.hrEmail, subject: `[HR-Portal] ${deptName} hat alle Offboarding-Aufgaben erledigt — ${name} (${displayId || ''})`, html: htmlBody } }];
} catch (error) {
  console.error('[offboarding-department-completed] Fehler:', error.message);
  return [{ json: { error: error.message, event: 'offboarding-department-completed' } }];
}

// ============================================================
// CREDO HR-Portal — Offboarding abgeschlossen
// Benachrichtigung an HR: Gesamter Vorgang komplett
// ============================================================

const CONFIG = {
  hrEmail: 'personal@credo-gruppe.de',
  portalUrl: 'https://hr.fes-credo.de'
};

try {
  const item = $input.first().json;
  const data = item.body || item;
  const { displayId, employeeName, employeeFirstName, employeeLastName, organization, lastWorkingDay, exitType, completedAt } = data;

  const name = employeeName || [employeeFirstName, employeeLastName].filter(Boolean).join(' ') || 'Unbekannt';
  const orgName = organization || 'CREDO';
  const lwdFormatted = lastWorkingDay ? new Date(lastWorkingDay).toLocaleDateString('de-DE', { day: '2-digit', month: '2-digit', year: 'numeric' }) : 'k.A.';
  const completedFormatted = completedAt ? new Date(completedAt).toLocaleDateString('de-DE', { day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit' }) : new Date().toLocaleDateString('de-DE');

  const htmlBody = `<!DOCTYPE html>
<html lang="de">
<head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"></head>
<body style="margin:0;padding:0;background-color:#f5f5f5;font-family:Calibri,Arial,sans-serif;">
<table width="100%" cellpadding="0" cellspacing="0" style="background-color:#f5f5f5;padding:20px 0;">
<tr><td align="center">
<table width="600" cellpadding="0" cellspacing="0" style="background-color:#ffffff;border-radius:8px;overflow:hidden;">
  <tr><td style="background-color:#005d6a;padding:25px 40px;">
    <h1 style="color:#ffffff;font-family:'ITC Avant Garde Gothic',Arial Black,Arial,sans-serif;font-size:22px;margin:0;">Offboarding abgeschlossen</h1>
  </td></tr>
  <tr><td style="padding:35px 40px;">
    <div style="background-color:#e8f5e9;border-left:4px solid #6BAA24;padding:15px 20px;border-radius:4px;margin:0 0 25px;">
      <p style="color:#2e7d32;font-size:15px;font-weight:bold;margin:0;">Offboarding-Vorgang vollst\u00e4ndig abgeschlossen</p>
    </div>
    <table cellpadding="8" cellspacing="0" style="width:100%;border-collapse:collapse;margin:0 0 25px;">
      <tr style="border-bottom:1px solid #eee;"><td style="color:#666;font-size:14px;width:160px;">Vorgang</td><td style="color:#333;font-size:14px;font-weight:bold;">${displayId || 'k.A.'}</td></tr>
      <tr style="border-bottom:1px solid #eee;"><td style="color:#666;font-size:14px;">Mitarbeiter/in</td><td style="color:#333;font-size:14px;font-weight:bold;">${name}</td></tr>
      <tr style="border-bottom:1px solid #eee;"><td style="color:#666;font-size:14px;">Einrichtung</td><td style="color:#333;font-size:14px;">${orgName}</td></tr>
      <tr style="border-bottom:1px solid #eee;"><td style="color:#666;font-size:14px;">Letzter Arbeitstag</td><td style="color:#333;font-size:14px;">${lwdFormatted}</td></tr>
      <tr><td style="color:#666;font-size:14px;">Abgeschlossen am</td><td style="color:#333;font-size:14px;font-weight:bold;">${completedFormatted}</td></tr>
    </table>
    <p style="color:#333;font-size:15px;line-height:1.6;margin:0 0 20px;">Alle Abteilungen haben ihre Offboarding-Aufgaben erledigt. Der Vorgang wurde als abgeschlossen markiert.</p>
    <table cellpadding="0" cellspacing="0" style="margin:0 auto 20px;"><tr><td align="center" style="background-color:#005d6a;border-radius:6px;">
      <a href="${CONFIG.portalUrl}/offboarding" target="_blank" style="display:inline-block;padding:12px 35px;color:#ffffff;font-size:15px;font-weight:bold;text-decoration:none;">Im HR-Portal oeffnen</a>
    </td></tr></table>
  </td></tr>
  <tr><td style="padding:0;"><table width="100%" cellpadding="0" cellspacing="0"><tr>
